function makeZip(files){const encoder=new TextEncoder(),parts=[],central=[];let offset=0;for(const file of files){const name=encoder.encode(file.name),data=file.data instanceof Uint8Array?file.data:new Uint8Array(file.data),crc=crc32(data),local=zipPart(30+name.length,(v,b)=>{v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0x0800,true);v.setUint16(8,0,true);v.setUint32(14,crc,true);v.setUint32(18,data.length,true);v.setUint32(22,data.length,true);v.setUint16(26,name.length,true);b.set(name,30)});parts.push(local,data);const entryOffset=offset;offset+=local.length+data.length;central.push(zipPart(46+name.length,(v,b)=>{v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0x0800,true);v.setUint16(10,0,true);v.setUint32(16,crc,true);v.setUint32(20,data.length,true);v.setUint32(24,data.length,true);v.setUint16(28,name.length,true);v.setUint32(42,entryOffset,true);b.set(name,46)}))}const centralSize=central.reduce((sum,x)=>sum+x.length,0),end=zipPart(22,v=>{v.setUint32(0,0x06054b50,true);v.setUint16(8,files.length,true);v.setUint16(10,files.length,true);v.setUint32(12,centralSize,true);v.setUint32(16,offset,true)});return new Blob([...parts,...central,end],{type:'application/zip'})}
function downloadBlob(blob,filename){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function urlImporterHtml(packeted){const waiting=packeted.length;return `<div class="url-importer"><p>Save this shortcut once, then use it from the public temporary-cover page whenever a packet is uploaded.</p><a class="secondary collector-link" id="collectorBookmark">Book URL Collector</a>${waiting?`<label>Paste collected Squarespace image URLs<textarea class="field" id="squarespaceUrls" rows="6" placeholder="Paste the URLs copied by Book URL Collector"></textarea></label><button class="secondary wide" id="matchUrls">Match and save book URLs</button><small id="matchStatus">${waiting} cover${waiting===1?' is':'s are'} waiting to be matched.</small>`:'<small>No uploaded covers are waiting to be matched right now.</small>'}</div>`}
function collectorBookmarklet(){return `javascript:(()=>{const u=[...new Set([...document.images].flatMap(i=>[i.currentSrc,i.src,i.getAttribute('data-src'),...(i.srcset||'').split(',').map(s=>s.trim().split(/\\s+/)[0])]).filter(x=>x&&x.includes('images.squarespace-cdn.com')).map(x=>x.replace(/&amp;/g,'&').split('?')[0]+'?format=1000w'))],t=u.join('\\n');if(!u.length){alert('BRAE: No Squarespace cover images found.');return}navigator.clipboard.writeText(t).then(()=>alert('BRAE: '+u.length+' Squarespace image URLs copied.'),()=>prompt('Copy these Squarespace image URLs:',t));})()`}
function bindUrlImporter(packeted){const bookmark=document.querySelector('#collectorBookmark'),button=document.querySelector('#matchUrls');if(!bookmark)return;bookmark.href=collectorBookmarklet();bookmark.onclick=event=>{event.preventDefault();toast('Drag Book URL Collector to your bookmarks bar—do not click it here.')};if(button)button.onclick=()=>matchSquarespaceUrls(packeted)}
async function matchSquarespaceUrls(packeted){const field=document.querySelector('#squarespaceUrls'),status=document.querySelector('#matchStatus'),button=document.querySelector('#matchUrls'),normalize=url=>String(url||'').replace(/&amp;/g,'&').split('?')[0],found=field.value.match(/https:\/\/images\.squarespace-cdn\.com\/[^\s"'<>]+/gi)||[],urls=[...new Set(found.map(url=>normalize(url)+'?format=1000w'))],matches=[],missing=[],duplicates=[];packeted.forEach(book=>{const id=book.id.toLowerCase(),oldBase=normalize(book.squarespaceCoverUrl),candidates=urls.filter(url=>{try{return decodeURIComponent(url).toLowerCase().includes(id)}catch(error){return url.toLowerCase().includes(id)}}),newCandidates=candidates.filter(url=>normalize(url)!==oldBase);if(newCandidates.length===1)matches.push({bookId:book.id,url:newCandidates[0]});else if(newCandidates.length>1)duplicates.push(book.id);else if(oldBase&&candidates.some(url=>normalize(url)===oldBase))matches.push({bookId:book.id,url:book.squarespaceCoverUrl});else missing.push(book.id)});if(missing.length||duplicates.length){status.textContent=`Not saved: ${missing.length} missing and ${duplicates.length} ambiguous matches.`;toast('URL matching is incomplete. Nothing was saved.');return}button.disabled=true;button.textContent='Saving matches…';try{await apiRequest('importSquarespaceUrls',{matches});matches.forEach(match=>{const book=books.find(b=>b.id===match.bookId);book.squarespaceCoverUrl=match.url;book.publicationStatus='Ready for Catalog';book.recordVersion++});toast(`${matches.length} Squarespace cover URLs matched and saved`);renderPublish()}catch(error){toast(error.message||'Squarespace URLs were not saved');button.disabled=false;button.textContent='Match and save URLs'}}
function humanizeAuditAction(value){return String(value||'Activity').toLowerCase().replaceAll('_',' ').replace(/\b\w/g,char=>char.toUpperCase())}
function formatAuditTime(value){const date=new Date(value);return Number.isNaN(date.getTime())?String(value||''):`${date.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'})} ${date.toLocaleTimeString('en-US',{hour:'numeric',minute:'2-digit'})}`}
function auditFilterPayload(page=auditState.page,pageSize=auditState.pageSize){return {page,pageSize,search:auditState.filters.search,auditAction:auditState.filters.action==='All'?'':auditState.filters.action,startDate:auditState.filters.startDate,endDate:auditState.filters.endDate}}
function renderAudit(){const state=auditState,pages=Math.max(1,Math.ceil(state.total/state.pageSize)),start=state.total?(state.page-1)*state.pageSize+1:0,end=Math.min(state.page*state.pageSize,state.total),actionOptions=['All',...state.actions];view.innerHTML=`<div class="page-head"><div><p class="eyebrow">ACCOUNTABILITY</p><h1>Audit Log</h1><p>Every review, edit, arrangement, and publication change recorded by Google Sheets.</p></div><div class="page-actions"><button class="secondary" id="refreshAudit" ${state.loading?'disabled':''}>Refresh</button><button class="primary" id="exportAudit" ${state.loading||!state.total?'disabled':''}>Export filtered CSV</button></div></div><form class="toolbar audit-toolbar" id="auditFilters"><input id="auditSearch" class="field search" placeholder="Search user, book ID, author, action or value" value="${escapeHtml(state.filters.search)}"><select id="auditAction" class="field">${actionOptions.map(action=>`<option value="${escapeHtml(action)}" ${state.filters.action===action?'selected':''}>${action==='All'?'All actions':humanizeAuditAction(action)}</option>`).join('')}</select><label>From<input id="auditStart" class="field" type="date" value="${escapeHtml(state.filters.startDate)}"></label><label>Through<input id="auditEnd" class="field" type="date" value="${escapeHtml(state.filters.endDate)}"></label><button class="secondary" type="submit">Apply filters</button><button class="link-btn" type="button" id="clearAudit">Clear</button></form>${state.error?`<div class="warning" role="alert">${escapeHtml(state.error)}</div>`:''}<div class="table-wrap"><div class="audit-loading" id="auditStatus" ${state.loading?'':'hidden'}>Loading audit history…</div>${!state.loading&&state.items.length?`<table class="table audit-table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Book</th><th>Field</th><th></th></tr></thead><tbody>${state.items.map((item,index)=>`<tr><td>${escapeHtml(formatAuditTime(item.timestamp))}</td><td><strong>${escapeHtml(item.user_email||'System')}</strong></td><td><span class="audit-action">${escapeHtml(humanizeAuditAction(item.action))}</span></td><td>${item.book_id?`<button class="book-link" data-audit-book="${escapeHtml(item.book_id)}">${escapeHtml(item.book_id)}</button><small class="muted audit-author">${escapeHtml(item.author_name)}</small>`:'—'}</td><td>${escapeHtml(item.field_name||'—')}</td><td><button class="link-btn" data-audit-detail="${index}">View change</button></td></tr>`).join('')}</tbody></table>`:!state.loading?`<div class="empty"><h2>No audit entries found</h2><p>Clear a filter or choose a different date range.</p></div>`:''}${state.total?`<div class="pagination"><span>Showing ${start}–${end} of ${state.total}</span><div class="audit-pages"><button class="secondary" id="auditPrev" ${state.page<=1||state.loading?'disabled':''}>← Previous</button><span>Page ${state.page} of ${pages}</span><button class="secondary" id="auditNext" ${state.page>=pages||state.loading?'disabled':''}>Next →</button></div></div>`:''}</div>`;bindAudit();if(!state.loaded&&!state.loading)loadAuditEntries()}
function bindAudit(){const form=document.querySelector('#auditFilters'),refresh=document.querySelector('#refreshAudit'),clear=document.querySelector('#clearAudit'),prev=document.querySelector('#auditPrev'),next=document.querySelector('#auditNext'),exportButton=document.querySelector('#exportAudit');if(form)form.onsubmit=event=>{event.preventDefault();auditState.filters={search:document.querySelector('#auditSearch').value.trim(),action:document.querySelector('#auditAction').value,startDate:document.querySelector('#auditStart').value,endDate:document.querySelector('#auditEnd').value};auditState.page=1;auditState.loaded=false;renderAudit()};if(clear)clear.onclick=()=>{auditState.filters={search:'',action:'All',startDate:'',endDate:''};auditState.page=1;auditState.loaded=false;renderAudit()};if(refresh)refresh.onclick=()=>{auditState.loaded=false;renderAudit()};if(prev)prev.onclick=()=>{auditState.page--;auditState.loaded=false;renderAudit()};if(next)next.onclick=()=>{auditState.page++;auditState.loaded=false;renderAudit()};if(exportButton)exportButton.onclick=exportAuditCsv;document.querySelectorAll('[data-audit-detail]').forEach(button=>button.onclick=()=>showAuditDetail(auditState.items[Number(button.dataset.auditDetail)]));document.querySelectorAll('[data-audit-book]').forEach(button=>button.onclick=()=>{const book=books.find(item=>item.id===button.dataset.auditBook);if(book)openBook(book);else toast('That book is not available in the current Review Hub data.')})}
async function loadAuditEntries(){auditState.loading=true;auditState.error='';const status=document.querySelector('#auditStatus');if(status)status.hidden=false;try{const result=await apiRequest('listAudit',auditFilterPayload());auditState.items=result.items||[];auditState.total=Number(result.total||0);auditState.actions=result.actions||[];auditState.loaded=true}catch(error){auditState.items=[];auditState.total=0;auditState.loaded=true;auditState.error=error.message||'The audit history could not be loaded.'}finally{auditState.loading=false;if(route==='audit')renderAudit()}}
function showAuditDetail(item){if(!item)return;modalRoot.innerHTML=`<div class="modal-backdrop" role="presentation"><section class="modal audit-detail-modal" role="dialog" aria-modal="true" aria-labelledby="auditDetailTitle"><h2 id="auditDetailTitle">${escapeHtml(humanizeAuditAction(item.action))}</h2><p>${escapeHtml(formatAuditTime(item.timestamp))} · ${escapeHtml(item.user_email||'System')}</p><dl class="audit-detail-list"><div><dt>Book</dt><dd>${escapeHtml(item.book_id||'—')} ${item.author_name?`· ${escapeHtml(item.author_name)}`:''}</dd></div><div><dt>Field</dt><dd>${escapeHtml(item.field_name||'—')}</dd></div><div><dt>Previous value</dt><dd>${escapeHtml(item.old_value||'—')}</dd></div><div><dt>New value</dt><dd>${escapeHtml(item.new_value||'—')}</dd></div><div><dt>Notes</dt><dd>${escapeHtml(item.notes||'—')}</dd></div><div><dt>Audit ID</dt><dd>${escapeHtml(item.audit_id||'—')}</dd></div></dl><div class="modal-actions"><button class="primary" id="closeAuditDetail">Close</button></div></section></div>`;modalRoot.querySelector('#closeAuditDetail').onclick=()=>modalRoot.innerHTML='';modalRoot.querySelector('.modal-backdrop').onclick=event=>{if(event.target===event.currentTarget)modalRoot.innerHTML=''}}
async function exportAuditCsv(){const button=document.querySelector('#exportAudit');button.disabled=true;button.textContent='Preparing CSV…';try{let page=1,total=Infinity,items=[];while(items.length<total){const result=await apiRequest('listAudit',auditFilterPayload(page,500));total=Number(result.total||0);items.push(...(result.items||[]));if(!(result.items||[]).length)break;page++;if(page>100)throw new Error('The filtered export is too large. Narrow the date range and try again.')}const headers=['audit_id','timestamp','user_email','action','book_id','author_name','field_name','old_value','new_value','notes'],rows=items.map(item=>headers.map(header=>item[header]||'')),csv='\ufeff'+[headers,...rows].map(row=>row.map(csvCell).join(',')).join('\r\n'),stamp=new Date().toISOString().slice(0,10);downloadBlob(new Blob([csv],{type:'text/csv;charset=utf-8'}),`BRAE-audit-log-${stamp}.csv`);toast(`${items.length} audit entries exported`)}catch(error){toast(error.message||'The audit export failed')}finally{button.disabled=false;button.textContent='Export filtered CSV'}}
function renderRequiredPasswordChange(){view.innerHTML=`<section class="password-gate panel"><p class="eyebrow">ACCOUNT SECURITY</p><h1>${passwordRecovery?'Choose a new password':'Change your temporary password'}</h1><p>${passwordRecovery?'Your reset link is active.':'You must replace the temporary password before entering the Review Hub.'}</p><form id="requiredPasswordForm" class="stack-form"><label>New password<input class="field" id="requiredPassword" type="password" autocomplete="new-password" required minlength="12"></label><label>Confirm password<input class="field" id="requiredPasswordConfirm" type="password" autocomplete="new-password" required minlength="12"></label><small>At least 12 characters with uppercase, lowercase, a number, and a symbol.</small><p id="requiredPasswordError" class="login-error" hidden></p><button class="primary" id="requiredPasswordButton">Save new password</button></form></section>`;document.querySelector('#requiredPasswordForm').onsubmit=e=>changeOwnPassword(e,true)}

function renderAdmin(){const superAdmin=adminData.is_super_admin,settings=Object.fromEntries((adminData.settings||[]).map(x=>[x.key,x.value]));view.innerHTML=`<div class="page-head"><div><p class="eyebrow">SYSTEM CONTROL</p><h1>Admin & Settings</h1><p>${superAdmin?'Manage staff, event configuration, and catalog genres.':'Manage your profile and view event configuration.'}</p></div>${superAdmin?'<button class="primary" id="addAdmin">Add staff member</button>':''}</div><section class="admin-grid"><div><article class="panel"><div class="panel-head"><h2>My account</h2><span class="status approved">Active</span></div><form id="profileForm" class="stack-form"><label>Display name<input class="field" id="ownDisplayName" value="${escapeHtml(currentUser.display_name||'')}" required></label><button class="secondary">Save name</button></form><form id="ownPasswordForm" class="stack-form divided"><label>New password<input class="field" id="ownPassword" type="password" autocomplete="new-password" minlength="12" required></label><label>Confirm password<input class="field" id="ownPasswordConfirm" type="password" autocomplete="new-password" minlength="12" required></label><small>At least 12 characters with uppercase, lowercase, a number, and a symbol.</small><button class="secondary">Change password</button></form></article>${superAdmin?teamPanel():''}</div><div><article class="panel"><div class="panel-head"><h2>Event settings</h2><span class="muted">${superAdmin?'Editable':'View only'}</span></div><form id="eventSettingsForm" class="settings-form">${settingField('event_year','Event year',settings.event_year,superAdmin,'number')}${settingField('ebook_event_dates','Full ebook dates',settings.ebook_event_dates,superAdmin)}${settingField('one_day_event_date','One-day date',settings.one_day_event_date,superAdmin)}${settingField('audiobook_event_date','Audiobook date',settings.audiobook_event_date,superAdmin)}${settingField('max_books_per_author_form','Max books / author',settings.max_books_per_author_form,superAdmin,'number')}<label class="toggle-row"><span>Auto-advance after decision</span><input id="setting_auto_advance_after_decision" type="checkbox" ${truthy(settings.auto_advance_after_decision)?'checked':''} ${superAdmin?'':'disabled'}></label>${superAdmin?'<button class="secondary">Save event settings</button>':''}</form></article><article class="panel genres-panel"><div class="panel-head"><h2>Genres</h2><span class="muted">${superAdmin?'Display labels and order':'View only'}</span></div><div id="genreSettings">${genreSettingsRows(superAdmin)}</div>${superAdmin?'<button class="secondary" id="saveGenres">Save genres</button>':''}<small class="muted admin-note">Submission form values remain unchanged so existing books continue to match correctly.</small></article></div></section>`;bindAdmin()}

function settingField(key,label,value,editable,type='text'){return `<label>${label}<input class="field" id="setting_${key}" type="${type}" value="${escapeHtml(String(value??''))}" ${editable?'':'disabled'}></label>`}
function truthy(value){return value===true||String(value).toLowerCase()==='true'}
function teamPanel(){const users=adminData.users||[];return `<article class="panel team-panel"><div class="panel-head"><h2>Team access</h2><span class="badge">${users.filter(u=>u.is_active).length} active</span></div><div class="team-list">${users.map(u=>`<div class="team-user" data-user-email="${escapeHtml(u.email)}"><div><strong>${escapeHtml(u.display_name||u.email)}</strong><small>${escapeHtml(u.email)} · ${escapeHtml(u.role)}${u.must_change_password?' · Temporary password':''}</small></div><span class="status ${u.is_active?'approved':'denied'}">${u.is_active?'Active':'Disabled'}</span><button class="secondary manage-user">Manage</button><button class="link-btn reset-user">Send reset</button></div>`).join('')||'<p class="empty">No staff records found.</p>'}</div></article>`}
function genreSettingsRows(editable){return (adminData.genres||[]).map((g,i)=>`<div class="admin-genre-row" data-genre-id="${escapeHtml(g.genre_id)}"><span class="drag-label">${i+1}</span><input class="field genre-name" value="${escapeHtml(g.display_name||g.form_value)}" ${editable?'':'disabled'}><label><input class="genre-active" type="checkbox" ${g.is_active?'checked':''} ${editable?'':'disabled'}> Active</label>${editable?`<span class="genre-move"><button class="link-btn genre-up" type="button" ${i?'':'disabled'}>↑</button><button class="link-btn genre-down" type="button" ${i===(adminData.genres.length-1)?'disabled':''}>↓</button></span>`:''}</div>`).join('')}

function bindAdmin(){document.querySelector('#profileForm').onsubmit=saveOwnProfile;document.querySelector('#ownPasswordForm').onsubmit=e=>changeOwnPassword(e,false);if(!adminData.is_super_admin)return;document.querySelector('#addAdmin').onclick=openAddAdmin;document.querySelectorAll('.manage-user').forEach(b=>b.onclick=()=>openManageUser(b.closest('.team-user').dataset.userEmail));document.querySelectorAll('.reset-user').forEach(b=>b.onclick=()=>sendPasswordReset(b.closest('.team-user').dataset.userEmail,b));document.querySelector('#eventSettingsForm').onsubmit=saveEventSettings;document.querySelector('#saveGenres').onclick=saveGenres;bindGenreMoves()}
function bindGenreMoves(){document.querySelectorAll('.genre-up,.genre-down').forEach(button=>button.onclick=()=>{const row=button.closest('.admin-genre-row'),sibling=button.classList.contains('genre-up')?row.previousElementSibling:row.nextElementSibling;if(sibling)row.parentElement.insertBefore(button.classList.contains('genre-up')?row:sibling,button.classList.contains('genre-up')?sibling:row);renumberGenreRows()})}
function renumberGenreRows(){const rows=[...document.querySelectorAll('.admin-genre-row')];rows.forEach((row,i)=>{row.querySelector('.drag-label').textContent=i+1;row.querySelector('.genre-up').disabled=!i;row.querySelector('.genre-down').disabled=i===rows.length-1})}
async function saveOwnProfile(e){e.preventDefault();const button=e.submitter,name=document.querySelector('#ownDisplayName').value.trim();button.disabled=true;try{await apiRequest('saveOwnProfile',{displayName:name});currentUser.display_name=name;document.querySelector('#profileName').textContent=name;toast('Your display name was saved.')}catch(error){toast(error.message||'Could not save your profile.')}finally{button.disabled=false}}
function validPassword(password){return password.length>=12&&/[a-z]/.test(password)&&/[A-Z]/.test(password)&&/\d/.test(password)&&/[^A-Za-z0-9]/.test(password)}
async function changeOwnPassword(e,required){e.preventDefault();const prefix=required?'requiredPassword':'ownPassword',password=document.querySelector(`#${prefix}`).value,confirm=document.querySelector(`#${prefix}Confirm`).value,button=e.submitter,error=required?document.querySelector('#requiredPasswordError'):null;if(error)error.hidden=true;if(password!==confirm){if(error){error.textContent='The passwords do not match.';error.hidden=false}else toast('The passwords do not match.');return}if(!validPassword(password)){if(error){error.textContent='Use at least 12 characters with uppercase, lowercase, a number, and a symbol.';error.hidden=false}else toast('Password does not meet the security requirements.');return}button.disabled=true;button.textContent='Saving…';try{const {error:updateError}=await supabaseClient.auth.updateUser({password});if(updateError)throw updateError;await apiRequest('completePasswordChange');currentUser.must_change_password=false;passwordRecovery=false;history.replaceState(null,'',location.pathname+location.search);toast('Password changed successfully.');if(required){route='dashboard';render()}else e.target.reset()}catch(err){if(error){error.textContent=err.message||'Could not change password.';error.hidden=false}else toast(err.message||'Could not change password.')}finally{button.disabled=false;button.textContent=required?'Save new password':'Change password'}}
function randomPassword(){const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*?';const bytes=new Uint32Array(18);crypto.getRandomValues(bytes);let value=[...bytes].map(n=>chars[n%chars.length]).join('');return `Aa1!${value}`}
function openAddAdmin(){modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>Add staff member</h2><p>Supabase and the Google Users sheet will be updated together.</p><form id="addAdminForm" class="stack-form"><label>Display name<input class="field" id="newAdminName" required></label><label>Email<input class="field" id="newAdminEmail" type="email" required></label><label>Role<select class="field" id="newAdminRole"><option>Admin</option><option>Reviewer</option><option>Super Admin</option></select></label><label>Temporary password<div class="inline-field"><input class="field" id="newAdminPassword" type="text" value="${randomPassword()}" required><button class="secondary" id="generatePassword" type="button">Generate</button></div></label><small>Copy this password before saving. It is shown here once and is never stored in Google Sheets.</small><div class="modal-actions"><button class="secondary" type="button" id="cancelAdmin">Cancel</button><button class="primary">Create account</button></div></form></div></div>`;document.querySelector('#cancelAdmin').onclick=()=>modalRoot.innerHTML='';document.querySelector('#generatePassword').onclick=()=>document.querySelector('#newAdminPassword').value=randomPassword();document.querySelector('#addAdminForm').onsubmit=createAdmin}
async function createAdmin(e){e.preventDefault();const button=e.submitter,payload={displayName:document.querySelector('#newAdminName').value.trim(),email:document.querySelector('#newAdminEmail').value.trim(),role:document.querySelector('#newAdminRole').value,temporaryPassword:document.querySelector('#newAdminPassword').value};button.disabled=true;button.textContent='Creating…';try{const result=await apiRequest('createAdminUser',payload);adminData.users.push(result.user);modalRoot.innerHTML='';renderAdmin();toast('Account created in Supabase and Google Sheets.')}catch(error){toast(error.message||'Could not create the account.');button.disabled=false;button.textContent='Create account'}}
function openManageUser(email){const user=adminData.users.find(u=>u.email===email);if(!user)return;modalRoot.innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>Manage staff member</h2><p>${escapeHtml(user.email)}</p><form id="manageAdminForm" class="stack-form"><label>Display name<input class="field" id="manageName" value="${escapeHtml(user.display_name||'')}" required></label><label>Role<select class="field" id="manageRole">${['Reviewer','Admin','Super Admin'].map(r=>`<option ${r===user.role?'selected':''}>${r}</option>`).join('')}</select></label><label class="toggle-row"><span>Account active</span><input id="manageActive" type="checkbox" ${user.is_active?'checked':''}></label><div class="modal-actions"><button class="secondary" type="button" id="cancelManage">Cancel</button><button class="primary">Save changes</button></div></form></div></div>`;document.querySelector('#cancelManage').onclick=()=>modalRoot.innerHTML='';document.querySelector('#manageAdminForm').onsubmit=e=>updateAdmin(e,user)}
async function updateAdmin(e,user){e.preventDefault();const button=e.submitter,payload={email:user.email,displayName:document.querySelector('#manageName').value.trim(),role:document.querySelector('#manageRole').value,isActive:document.querySelector('#manageActive').checked};button.disabled=true;try{await apiRequest('updateAdminUser',payload);Object.assign(user,{display_name:payload.displayName,role:payload.role,is_active:payload.isActive,can_publish:payload.role!=='Reviewer',can_arrange:payload.role!=='Reviewer'});modalRoot.innerHTML='';renderAdmin();toast('Staff access updated.')}catch(error){toast(error.message||'Could not update staff access.');button.disabled=false}}
async function sendPasswordReset(email,button){if(!confirm(`Send a password reset email to ${email}?`))return;button.disabled=true;try{await apiRequest('sendAdminPasswordReset',{email});toast(`Password reset email sent to ${email}.`)}catch(error){toast(error.message||'Could not send the reset email.')}finally{button.disabled=false}}
async function saveEventSettings(e){e.preventDefault();const button=e.submitter,settings={event_year:document.querySelector('#setting_event_year').value,ebook_event_dates:document.querySelector('#setting_ebook_event_dates').value,one_day_event_date:document.querySelector('#setting_one_day_event_date').value,audiobook_event_date:document.querySelector('#setting_audiobook_event_date').value,max_books_per_author_form:document.querySelector('#setting_max_books_per_author_form').value,auto_advance_after_decision:document.querySelector('#setting_auto_advance_after_decision').checked};button.disabled=true;try{await apiRequest('saveEventSettings',{settings});Object.entries(settings).forEach(([key,value])=>{const item=adminData.settings.find(x=>x.key===key);if(item)item.value=value});toast('Event settings saved.')}catch(error){toast(error.message||'Could not save event settings.')}finally{button.disabled=false}}
async function saveGenres(){const button=document.querySelector('#saveGenres'),items=[...document.querySelectorAll('.admin-genre-row')].map(row=>({genre_id:row.dataset.genreId,display_name:row.querySelector('.genre-name').value.trim(),is_active:row.querySelector('.genre-active').checked}));button.disabled=true;try{await apiRequest('saveGenreSettings',{genres:items});adminData.genres=items.map((item,index)=>({...item,display_order:index+1,form_value:(adminData.genres.find(g=>g.genre_id===item.genre_id)||{}).form_value}));genres=adminData.genres.filter(g=>g.is_active).map(g=>g.display_name||g.form_value);renderAdmin();toast('Genre settings saved.')}catch(error){toast(error.message||'Could not save genres.')}finally{if(document.querySelector('#saveGenres'))document.querySelector('#saveGenres').disabled=false}}
function bindGo(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{route=b.dataset.go;render()});document.querySelectorAll('[data-next]').forEach(b=>b.onclick=()=>{const next=books.find(book=>book.status==='Pending'&&!reviewLocks.has(book.id));if(next)openBook(next);else toast('No unlocked pending books are currently available.')})}
function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2600)}

function renderPublish(){const approved=books.filter(b=>b.status==='Approved'),published=approved.filter(b=>b.publicationStatus==='Published'),readyCatalog=approved.filter(b=>b.publicationStatus==='Ready for Catalog'),packeted=approved.filter(b=>b.publicationStatus.startsWith('Packet Created')),eligible=publishEligibleBooks();view.innerHTML=`<div class="page-head"><div><p class="eyebrow">SQUARESPACE CATALOG RELEASE</p><h1>Publish Catalog</h1><p>Four steps. Complete them in order for each publication batch.</p></div><span class="status updated">${eligible.length+packeted.length+readyCatalog.length} in progress</span></div>${publishNotice?`<div class="publish-success" role="status">${escapeHtml(publishNotice)}</div>`:''}<section class="publish-status-strip"><span><strong>${eligible.length}</strong> ready for packet</span><span><strong>${packeted.length}</strong> waiting for URLs</span><span><strong>${readyCatalog.length}</strong> ready for Squarespace</span><span><strong>${published.length}</strong> published</span></section><details class="panel squarespace-setup"><summary>One-time Squarespace catalog setup</summary>${catalogSetupHtml()}</details><section class="publish-compact"><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">1</span><div><h2>Create and upload the publication packet</h2><p>Click <strong>Create Publication Packet</strong>, upload its images to Squarespace <strong>Temp Cover Uploads</strong>, and save the page.</p></div></div><div class="step-control"><div class="warning" id="packetStatus">${eligible.length?'The next packet will contain only new or changed records.':'There are no new or changed records waiting for a packet.'}</div><button class="primary" id="createPacket" ${eligible.length&&currentUser?.can_publish?'':'disabled'}>Create Publication Packet</button></div><details class="publish-help"><summary>Show how to upload covers</summary><ol><li>Download and unzip the publication packet.</li><li>Open <strong>Pages → Not Linked → Temp Cover Uploads</strong> in Squarespace.</li><li>Edit the gallery and upload every image from the packet’s <strong>covers</strong> folder.</li><li>Keep all filenames unchanged, wait for every upload to finish, then save.</li></ol><div class="publish-guide"><figure><img src="assets/publish-help/step1-01-pages.png" alt="Squarespace Website menu with Pages circled"><figcaption>1. Open Pages.</figcaption></figure><figure><img src="assets/publish-help/step1-02-temp-cover-uploads.png" alt="Temp Cover Uploads page and Edit button circled"><figcaption>2. Select Temp Cover Uploads and click Edit.</figcaption></figure><figure><img src="assets/publish-help/step1-03-edit-gallery.png" alt="Edit Gallery button circled"><figcaption>3. Click Edit Gallery.</figcaption></figure><figure><img src="assets/publish-help/step1-04-upload-images.png" alt="Upload Images option circled"><figcaption>4. Click plus, then Upload Images.</figcaption></figure></div></details></article><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">2</span><div><h2>Collect and match the cover URLs</h2><p>Add <strong>Book URL Collector</strong> to the bookmarks bar once. Open <a href="https://www.brae.website/temp-cover-uploads" target="_blank" rel="noopener">Temp Cover Uploads ↗</a>, click the shortcut, then paste the copied URLs below.</p></div></div>${urlImporterHtml(packeted)}</article><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">3</span><div><h2>Update the changed Squarespace data pages</h2><p>Generate once, then replace the single complete data code on each listed hidden page. Multipart data appears only if a page exceeds Squarespace’s safe size.</p></div></div>${catalogPublisherHtml(readyCatalog,published)}</article><article class="panel publish-action-card"><div class="compact-step-head"><span class="step-number">4</span><div><h2>Confirm the catalog update</h2><p>Only confirm after every affected public catalog page has been checked.</p></div></div>${catalogConfirmationHtml()}</article></section>`;const button=document.querySelector('#createPacket');if(button)button.onclick=createPublicationPacket;bindUrlImporter(packeted);bindCatalogPublisher(readyCatalog,published);bindCatalogSetup()}

function formatCodeSize(bytes){return bytes<1024?`${bytes} bytes`:`${(bytes/1024).toFixed(1)} KB`}
function catalogPublisherHtml(readyCatalog,published){if(!readyCatalog.length&&!catalogDraft)return `<div class="step-control muted">No batch is Ready for Squarespace yet.</div>`;const page=catalogDraft?.pages[catalogDraft.selectedIndex||0],block=page?.blocks[catalogDraft.blockIndex||0],multipart=page?.blocks.length>1;return `<div class="catalog-publisher"><div class="catalog-actions"><button class="primary" id="generateCatalog" ${currentUser?.can_publish?'':'disabled'}>Generate changed pages</button>${catalogDraft?`<button class="secondary" id="copyCatalog">Copy ${multipart?'selected part':'complete page code'}</button><button class="secondary" id="downloadBlock">Download ${multipart?'selected part':'page'} .txt</button><button class="secondary" id="downloadCatalog">Download all changed pages</button>`:''}</div>${catalogDraft?`<label class="catalog-code-label">Affected catalog page<select class="field catalog-page-select" id="catalogSnippet">${catalogDraft.pages.map((item,index)=>`<option value="${index}" ${index===catalogDraft.selectedIndex?'selected':''}>${escapeHtml(item.label)} · ${item.count} book${item.count===1?'':'s'}</option>`).join('')}</select></label><div class="catalog-page-note"><strong>Hidden data page:</strong> ${escapeHtml(page.dataPath)}<br><strong>Visible cover sections needed:</strong> ${page.slotCount} (${page.count} books, up to 50 per section)<br><strong>Generated code size:</strong> ${formatCodeSize(page.totalBytes)}${multipart?`<br><strong>Size fallback:</strong> ${page.blocks.length} numbered parts are required.`:''}</div>${page.sizeWarning?`<div class="warning">${escapeHtml(page.sizeWarning)}</div>`:''}<label class="catalog-code-label">${multipart?`Data part<select class="field catalog-page-select" id="catalogBlock">${page.blocks.map((item,index)=>`<option value="${index}" ${index===(catalogDraft.blockIndex||0)?'selected':''}>Part ${index+1} of ${page.blocks.length} · ${formatCodeSize(item.bytes)}</option>`).join('')}</select>`:'Complete page data'}<textarea class="field catalog-code" id="catalogCode" rows="10" readonly>${escapeHtml(block.code)}</textarea></label><div class="warning">Update all ${catalogDraft.pages.length} listed hidden data page${catalogDraft.pages.length===1?'':'s'}, then verify the corresponding public pages.</div>`:`<p class="muted">${readyCatalog.length} record${readyCatalog.length===1?' is':'s are'} ready. Only affected pages will be generated, and each receives its complete current catalog.</p>`}<details class="publish-help"><summary>Show how to update catalog data</summary><ol><li>Choose an affected page and note its hidden data-page address.</li><li>Copy or download its complete page code and replace the single code block on that hidden page.</li><li>If the size fallback appears, replace all numbered parts instead.</li><li>Save the hidden page and verify the matching public page. Its loader automatically distributes books among the 50-book sections.</li></ol><div class="guide-media-slot"><strong>Visual guide</strong><span>A screenshot sequence or short screen recording can be added here later.</span></div></details></div>`}

function catalogConfirmationHtml(){if(!catalogDraft)return '<p class="muted">Generate the changed pages in Step 3 before confirming publication.</p><button class="primary wide" disabled>Confirm catalog published</button>';return `<label class="publish-confirm"><input type="checkbox" id="catalogVerified"> I updated the Squarespace data and verified every affected catalog page</label><button class="primary wide" id="confirmCatalog" disabled>Confirm catalog published</button><small class="muted">This marks the ${catalogDraft.readyIds.length} current Ready for Catalog record${catalogDraft.readyIds.length===1?'':'s'} as Published.</small>`}
function bindCatalogPublisher(readyCatalog,published){const generate=document.querySelector('#generateCatalog');if(generate)generate.onclick=()=>{try{catalogDraft=buildCatalogDraft(readyCatalog,published);publishNotice=`${catalogDraft.pages.length} changed catalog page${catalogDraft.pages.length===1?' was':'s were'} generated. Each contains its complete current book list. Nothing has been marked Published.`;renderPublish()}catch(error){toast(error.message)}};if(!catalogDraft)return;const renderSelection=()=>renderPublish(),select=document.querySelector('#catalogSnippet'),blockSelect=document.querySelector('#catalogBlock'),copy=document.querySelector('#copyCatalog'),downloadBlock=document.querySelector('#downloadBlock'),download=document.querySelector('#downloadCatalog'),verified=document.querySelector('#catalogVerified'),confirm=document.querySelector('#confirmCatalog');if(select)select.onchange=()=>{catalogDraft.selectedIndex=Number(select.value);catalogDraft.blockIndex=0;renderSelection()};if(blockSelect)blockSelect.onchange=()=>{catalogDraft.blockIndex=Number(blockSelect.value);document.querySelector('#catalogCode').value=catalogDraft.pages[catalogDraft.selectedIndex].blocks[catalogDraft.blockIndex].code};if(copy)copy.onclick=async()=>{const page=catalogDraft.pages[catalogDraft.selectedIndex||0],block=page.blocks[catalogDraft.blockIndex||0];try{await navigator.clipboard.writeText(block.code);toast(`${page.label} ${page.blocks.length>1?`part ${block.index}`:'page code'} copied`)}catch(error){document.querySelector('#catalogCode').select();toast('Clipboard access was blocked. The code is selected for copying.')}};if(downloadBlock)downloadBlock.onclick=()=>{const page=catalogDraft.pages[catalogDraft.selectedIndex||0],block=page.blocks[catalogDraft.blockIndex||0];downloadBlob(new Blob([block.code],{type:'text/plain;charset=utf-8'}),block.filename)};if(download)download.onclick=()=>{const files=catalogDraft.pages.flatMap(page=>page.blocks.map(block=>({name:page.blocks.length>1?`${page.slug}/${block.filename}`:block.filename,data:new TextEncoder().encode(block.code)})));files.push({name:'READ-ME.txt',data:new TextEncoder().encode('BRAE SQUARESPACE CATALOG DATA\r\n\r\nOnly changed pages are included. Normally each page has one complete .txt file. Replace the single code block on the matching hidden Squarespace data page. If a page folder contains numbered parts, its complete code exceeded the safe Squarespace size and every numbered part must be installed in order.\r\n')});downloadBlob(makeZip(files),`BRAE-Squarespace-data-${catalogDraft.version}.zip`)};if(verified)verified.onchange=()=>confirm.disabled=!verified.checked;if(confirm)confirm.onclick=confirmCatalogPublished}

function slugify(value){return String(value||'other').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function catalogPageForBook(book){if(book.sourceType==='AUDIOBOOK')return {key:'audiobooks',label:'Audiobooks',slug:'audiobooks'};if(book.sourceType==='ONE_DAY_EBOOK')return {key:'one-day-ebooks',label:'One-Day Free Books',slug:'one-day-ebooks'};const genre=book.genre||'Other',slug=slugify(genre);return {key:`genre--${slug}`,label:genre,slug}}
function catalogPageDefinitions(){const definitions=[{key:'audiobooks',label:'Audiobooks',slug:'audiobooks'},{key:'one-day-ebooks',label:'One-Day Free Books',slug:'one-day-ebooks'},...genres.map(genre=>({key:`genre--${slugify(genre)}`,label:genre,slug:slugify(genre)}))],seen=new Set();return definitions.filter(page=>!seen.has(page.key)&&seen.add(page.key))}
function catalogDataCode(page,payload,part=1){const safeJson=JSON.stringify(payload).replaceAll('</','<\\/');return `<script type="application/json" data-brae-catalog="${page.key}" data-brae-part="${part}">${safeJson}</script>`}
function buildCatalogDraft(readyCatalog,published){
  const seen=new Set();
  const catalogBooks=[...published,...readyCatalog].filter(book=>{
    if(seen.has(book.id))return false;
    seen.add(book.id);
    return true;
  });
  const invalid=catalogBooks.filter(book=>!/^https:\/\/images\.squarespace-cdn\.com\//i.test(book.squarespaceCoverUrl)||!/^https?:\/\//i.test(book.url));
  if(invalid.length)throw new Error(`Catalog blocked: ${invalid.length} book${invalid.length===1?' has':'s have'} a missing cover or invalid destination link.`);
  const affected=new Set();
  readyCatalog.forEach(book=>{
    affected.add(catalogPageForBook(book).key);
    if(book.publishedPageKey)affected.add(book.publishedPageKey);
  });
  const definitions=new Map(catalogPageDefinitions().map(page=>[page.key,page]));
  catalogBooks.forEach(book=>{
    const page=catalogPageForBook(book);
    if(!definitions.has(page.key))definitions.set(page.key,page);
  });
  const pages=[...affected].map(key=>definitions.get(key)||{key,label:key,slug:slugify(key)}).map(page=>{
    const list=catalogBooks.filter(book=>catalogPageForBook(book).key===page.key).sort((a,b)=>Number(b.pin)-Number(a.pin)||(a.order||999999)-(b.order||999999)||a.title.localeCompare(b.title));
    const payload=list.map(book=>({id:book.id,t:book.title,a:book.author,u:book.url,c:book.squarespaceCoverUrl}));
    const encoder=new TextEncoder(),completeCode=catalogDataCode(page,payload),totalBytes=encoder.encode(completeCode).length,safeLimit=350*1024,warningLimit=300*1024;
    let chunks=[payload];
    if(totalBytes>safeLimit){
      chunks=[];
      let current=[];
      payload.forEach(item=>{
        const candidate=[...current,item];
        if(current.length&&encoder.encode(catalogDataCode(page,candidate)).length>safeLimit){chunks.push(current);current=[item]}else current=candidate;
      });
      if(current.length||!chunks.length)chunks.push(current);
    }
    const blocks=chunks.map((chunk,index)=>{
      const code=catalogDataCode(page,chunk,index+1),multipart=chunks.length>1;
      return {index:index+1,code,bytes:encoder.encode(code).length,filename:multipart?`${page.slug}--data-part-${String(index+1).padStart(2,'0')}.txt`:`${page.slug}--complete-page.txt`,count:chunk.length};
    });
    const sizeWarning=blocks.length>1?`This page is ${formatCodeSize(totalBytes)} and exceeds the safe single-block limit. Squarespace requires ${blocks.length} numbered data parts.`:totalBytes>=warningLimit?`This page is approaching Squarespace’s code-block limit. It still fits as one complete file, but future additions may trigger the automatic multipart fallback.`:'';
    return {...page,dataPath:`/brae-data-${page.slug}`,count:list.length,slotCount:Math.max(1,Math.ceil(list.length/50)),totalBytes,blocks,sizeWarning};
  });
  return {pages,selectedIndex:0,blockIndex:0,total:catalogBooks.length,readyIds:readyCatalog.map(book=>book.id),pageAssignments:Object.fromEntries(readyCatalog.map(book=>[book.id,catalogPageForBook(book).key])),version:new Date().toISOString().replace(/\D/g,'').slice(0,14)};
}

function catalogSetupHtml(){const pages=catalogPageDefinitions(),selected=pages[0];return `<div class="setup-body"><p>Do this once for each catalog page. The public page will then read its books from a hidden Squarespace data page; routine publishing never requires editing the public page code.</p><label>Catalog page<select class="field catalog-page-select" id="setupPage">${pages.map((page,index)=>`<option value="${index}">${escapeHtml(page.label)}</option>`).join('')}</select></label><div class="catalog-page-note" id="setupPath"><strong>Hidden data page:</strong> /brae-data-${selected.slug}</div><div class="catalog-actions"><button class="secondary" id="copyLoader">Copy one-time loader</button><button class="secondary" id="downloadLoader">Download loader .txt</button><button class="secondary" id="copySlot">Copy 50-book section</button><button class="secondary" id="downloadSlot">Download section .txt</button></div><ol><li>Create the listed hidden page under <strong>Not Linked</strong>.</li><li>Add the loader code once to the matching public catalog page.</li><li>Add a separate code section containing the 50-book section code. Duplicate that section for each group of 50 books.</li><li>Place an ordinary Squarespace ad section between those book sections. Extra empty book sections hide automatically.</li></ol></div>`}
function catalogLoaderCode(page){return `<script>(()=>{const K=${JSON.stringify(page.key)},U=${JSON.stringify(`/brae-data-${page.slug}`)};function esc(v){return String(v||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function draw(){fetch(U,{cache:'no-store'}).then(r=>{if(!r.ok)throw Error('Catalog data unavailable');return r.text()}).then(html=>{const doc=new DOMParser().parseFromString(html,'text/html'),parts=[...doc.querySelectorAll('script[data-brae-catalog="'+K+'"]')].sort((a,b)=>Number(a.dataset.braePart)-Number(b.dataset.braePart)),books=parts.flatMap(node=>{try{return JSON.parse(node.textContent)}catch(e){return[]}}),slots=[...document.querySelectorAll('.brae-catalog-slot[data-brae-page="'+K+'"]')],editing=!!document.querySelector('.sqs-edit-mode-active')||document.body.classList.contains('sqs-edit-mode-active');slots.forEach((slot,index)=>{const list=books.slice(index*50,index*50+50),section=slot.closest('section.page-section,section[data-section-id]')||slot;slot.innerHTML=list.map(b=>'<a class="brae-book" href="'+esc(b.u)+'" target="_blank" rel="noopener noreferrer" aria-label="Open '+esc(b.t)+' by '+esc(b.a)+'"><img src="'+esc(b.c)+'" alt="'+esc(b.t)+' by '+esc(b.a)+'" loading="lazy" decoding="async"></a>').join('');slot.hidden=!list.length&&!editing;if(!list.length&&!editing){section.style.setProperty('display','none','important');section.setAttribute('aria-hidden','true')}else{section.style.removeProperty('display');section.removeAttribute('aria-hidden')}});document.querySelectorAll('.brae-catalog-warning[data-brae-page="'+K+'"]').forEach(node=>node.remove());const required=Math.ceil(books.length/50);if(slots.length<required){const warning=document.createElement('p');warning.className='brae-catalog-warning';warning.dataset.braePage=K;warning.textContent='BRAE catalog setup warning: '+required+' cover sections are required, but only '+slots.length+' were found.';(slots[slots.length-1]||document.body).after(warning)}}).catch(error=>console.error('BRAE catalog:',error))}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',draw):draw()})();</script><style>.brae-catalog-slot{--brae-gap:clamp(1rem,2.2vw,1.8rem);display:flex;flex-wrap:wrap;justify-content:center;align-items:flex-start;gap:var(--brae-gap);width:100%;height:auto}.brae-book{display:block;box-sizing:border-box;flex:0 1 calc((100% - (4 * var(--brae-gap)))/5);min-width:0;border-radius:12px;outline:none;text-decoration:none;transition:transform .24s ease,filter .24s ease}.brae-book img{display:block;width:100%;height:auto;aspect-ratio:2/3;object-fit:cover;border-radius:12px;background:#eee;box-shadow:0 14px 28px rgba(25,14,10,.24),0 4px 10px rgba(25,14,10,.14);transition:box-shadow .24s ease}.brae-book:hover,.brae-book:focus-visible{transform:translateY(-7px) scale(1.025);filter:saturate(1.04)}.brae-book:hover img,.brae-book:focus-visible img{box-shadow:0 22px 42px rgba(25,14,10,.30),0 7px 16px rgba(25,14,10,.17)}.brae-catalog-warning{padding:12px 14px;background:#fff3cd;border:1px solid #e0b94d;color:#5d4100;font-weight:700}@media(max-width:900px){.brae-book{flex-basis:calc((100% - (3 * var(--brae-gap)))/4)}}@media(max-width:700px){.brae-catalog-slot{--brae-gap:.9rem}.brae-book{flex-basis:calc((100% - (2 * var(--brae-gap)))/3)}}@media(max-width:430px){.brae-book{flex-basis:calc((100% - var(--brae-gap))/2)}.brae-book,.brae-book img{border-radius:8px}}@media(prefers-reduced-motion:reduce){.brae-book,.brae-book img{transition:none}.brae-book:hover,.brae-book:focus-visible{transform:none}}</style>`}
function catalogSlotCode(page){return `<div class="brae-catalog-slot" data-brae-page="${page.key}" aria-live="polite"></div>`}
function bindCatalogSetup(){const select=document.querySelector('#setupPage');if(!select)return;const pages=catalogPageDefinitions(),current=()=>pages[Number(select.value)||0],saveText=(text,name)=>downloadBlob(new Blob([text],{type:'text/plain;charset=utf-8'}),name),copy=async(text,label)=>{try{await navigator.clipboard.writeText(text);toast(`${label} copied`)}catch(error){toast('Clipboard access was blocked. Use the .txt download instead.')}};select.onchange=()=>{document.querySelector('#setupPath').innerHTML=`<strong>Hidden data page:</strong> /brae-data-${current().slug}`};document.querySelector('#copyLoader').onclick=()=>copy(catalogLoaderCode(current()),`${current().label} loader`);document.querySelector('#downloadLoader').onclick=()=>saveText(catalogLoaderCode(current()),`${current().slug}--one-time-loader.txt`);document.querySelector('#copySlot').onclick=()=>copy(catalogSlotCode(current()),`${current().label} section`);document.querySelector('#downloadSlot').onclick=()=>saveText(catalogSlotCode(current()),`${current().slug}--50-book-section.txt`)}

async function confirmCatalogPublished(){if(!catalogDraft?.readyIds.length){toast('There is no Ready for Catalog batch to publish');return}const button=document.querySelector('#confirmCatalog');button.disabled=true;button.textContent='Recording publication…';try{const result=await apiRequest('markCatalogPublished',{bookIds:catalogDraft.readyIds,pageAssignments:catalogDraft.pageAssignments,catalogVersion:catalogDraft.version,totalBooks:catalogDraft.total}),readySet=new Set(catalogDraft.readyIds);books.forEach(book=>{if(readySet.has(book.id)){book.publicationStatus='Published';book.published=true;book.publishedPageKey=catalogDraft.pageAssignments[book.id]||book.publishedPageKey;book.recordVersion++}});metrics.published=books.filter(b=>b.status==='Approved'&&b.publicationStatus==='Published').length;publishNotice=`Catalog ${result.catalogVersion||catalogDraft.version} was confirmed. ${catalogDraft.readyIds.length} record${catalogDraft.readyIds.length===1?' is':'s are'} now Published.`;catalogDraft=null;toast('Catalog publication recorded in Google');renderPublish()}catch(error){toast(error.message||'Publication was not recorded');button.disabled=false;button.textContent='Confirm catalog published'}}
